create or replace function public.shop(sid text, unq boolean) returns jsonb language plpgsql security definer set search_path = public as $$ declare p profiles%rowtype; ids text[] := array['t1','t2','t3','f1','f2','f3','o1','o2','o3']; pr int[] := array[150,300,700,200,400,600,400,600,900]; vs text[] := array['Vigia Insone','Corvo do Conde','Eleito da Lua Rubra','#d23a4c','#f3d178','#7fb0e8','mago','patrulheiro','cavaleiro']; ix int := array_position(ids, sid); begin if ix is null then raise exception 'item inválido'; end if; perform me(); select * into p from profiles where id = auth.uid() for update; if not (sid = any(p.own)) then if p.gold < pr[ix] then raise exception 'ouro insuficiente'; end if; update profiles set gold = gold - pr[ix], own = own || sid where id = p.id; end if; update profiles set eq = case when unq then eq - substr(sid,1,1) else eq || jsonb_build_object(substr(sid,1,1), vs[ix]) end where id = p.id; return me(); end $$;
